<?php
require dirname(__DIR__).'/bootstrap.php';require_admin();$adminTitle='Quản lý bình luận';
if(isset($_GET['action'],$_GET['id'])){
 $id=(int)$_GET['id'];$act=$_GET['action'];
 if($act==='hide')db()->prepare("UPDATE comments SET moderation_status='hidden' WHERE id=?")->execute([$id]);
 if($act==='publish')db()->prepare("UPDATE comments SET moderation_status='published' WHERE id=?")->execute([$id]);
 if($act==='delete')db()->prepare("UPDATE comments SET moderation_status='deleted' WHERE id=?")->execute([$id]);
 header('Location: comments.php');exit;
}
if(isset($_POST['ban_email'])){check_csrf();$email=strtolower(trim($_POST['email']??''));$hours=(int)($_POST['hours']??24);$reason=trim($_POST['reason']??'Admin ban');$per=!empty($_POST['permanent'])?1:0;$ends=$per?null:date('Y-m-d H:i:s',time()+max(1,$hours)*3600);db()->prepare("INSERT INTO comment_bans(email,reason,starts_at,ends_at,permanent,created_by) VALUES(?,?,?,?,?,?)")->execute([$email,$reason,date('Y-m-d H:i:s'),$ends,$per,'admin']);header('Location: comments.php');exit;}
if(isset($_GET['unban'])){db()->prepare("UPDATE comment_bans SET ends_at=NOW(),permanent=0 WHERE id=?")->execute([(int)$_GET['unban']]);header('Location: comments.php');exit;}
$page=max(1,(int)($_GET['page']??1));$per=20;$offset=($page-1)*$per;$filter=$_GET['status']??'all';$where='';$params=[];if(in_array($filter,['published','hidden','deleted'],true)){$where='WHERE moderation_status=?';$params[]=$filter;}$st=db()->prepare("SELECT COUNT(*) FROM comments $where");$st->execute($params);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;$st=db()->prepare("SELECT c.*,m.name movie_name FROM comments c JOIN movies m ON m.id=c.movie_id $where ORDER BY c.created_at DESC,c.id DESC LIMIT $per OFFSET $offset");$st->execute($params);$rows=$st->fetchAll();$bans=db()->query("SELECT * FROM comment_bans WHERE permanent=1 OR ends_at>NOW() ORDER BY created_at DESC LIMIT 30")->fetchAll();require __DIR__.'/_header.php';
?>
<div class="admin-head"><div><small>MODERATION</small><h1>Quản lý bình luận</h1><p>Ẩn, đăng lại, xóa hoặc hạn chế theo email.</p></div></div>
<section class="admin-card"><div class="filters"><a href="comments.php" class="<?=$filter==='all'?'active':''?>">Tất cả</a><a href="?status=published" class="<?=$filter==='published'?'active':''?>">Đã đăng</a><a href="?status=hidden" class="<?=$filter==='hidden'?'active':''?>">Đang chờ</a><a href="?status=deleted" class="<?=$filter==='deleted'?'active':''?>">Đã xóa</a></div>
<div class="table-wrap"><table class="admin-table"><tr><th>Người dùng</th><th>Phim</th><th>Bình luận</th><th>Điểm bot</th><th>Trạng thái</th><th></th></tr><?php foreach($rows as $r): ?><tr><td><b><?=e($r['display_name'])?></b><br><small><?=e($r['email'])?></small></td><td><?=e($r['movie_name'])?></td><td><div class="comment-admin-text"><?=nl2br(e($r['body']))?></div><?php if($r['flag_reason']): ?><small class="flag">⚠ <?=e($r['flag_reason'])?></small><?php endif;?></td><td><?=e((string)$r['moderation_score'])?></td><td><?=e($r['moderation_status'])?></td><td><div class="actions"><?php if($r['moderation_status']!=='published'): ?><a class="btn" href="?action=publish&id=<?=$r['id']?>">Đăng</a><?php endif;?><?php if($r['moderation_status']==='published'): ?><a class="btn" href="?action=hide&id=<?=$r['id']?>">Ẩn</a><?php endif;?><a class="btn red" href="?action=delete&id=<?=$r['id']?>" onclick="return confirm('Xóa bình luận?')">Xóa</a><button type="button" class="btn ban-email" data-email="<?=e($r['email'])?>">Ban email</button></div></td></tr><?php endforeach;?></table></div></section>
<div class="admin-grid"><section class="admin-card"><h2>Ban email</h2><form class="admin-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input id="banEmail" name="email" type="email" required></label><label>Số giờ (bỏ qua nếu vĩnh viễn)<input name="hours" type="number" min="1" value="24"></label><label>Lý do<input name="reason" value="Vi phạm nội quy bình luận"></label><label><input type="checkbox" name="permanent"> Ban vĩnh viễn</label><button class="btn primary">Hạn chế</button></form></section><section class="admin-card"><h2>Email đang bị hạn chế</h2><div class="table-wrap"><table class="admin-table"><tr><th>Email</th><th>Đến</th><th>Lý do</th><th></th></tr><?php foreach($bans as $b): ?><tr><td><?=e($b['email'])?></td><td><?=$b['permanent']?'Vĩnh viễn':e($b['ends_at'])?></td><td><?=e($b['reason'])?></td><td><a class="btn" href="?unban=<?=$b['id']?>">Gỡ</a></td></tr><?php endforeach;?></table></div></section></div>
<div class="admin-pagination"><?php for($i=1;$i<=$pages;$i++): ?><a class="<?=$i===$page?'active':''?>" href="?status=<?=urlencode($filter)?>&page=<?=$i?>"><?=$i?></a><?php endfor; ?><span><?=$total?> bình luận</span></div>
<script>document.querySelectorAll('.ban-email').forEach(b=>b.addEventListener('click',()=>{document.getElementById('banEmail').value=b.dataset.email;window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'});}));</script>
<?php require __DIR__.'/_footer.php'; ?>
